class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Check if either string is empty
        if not s or not t:
            return 0

        # Create a matrix to store the longest palindromic subsequence lengths
        dp = [[0] * len(t) for _ in range(len(s))]

        # Fill the diagonal of the DP table
        for i in range(len(s)):
            if s[i] == t[i]:
                dp[i][i] = 2

        # Fill the rest of the DP table
        for length in range(2, min(len(s), len(t)) + 1):
            for i in range(len(s) - length + 1):
                j = i + length - 1
                if s[i] == t[j]:
                    dp[i][j] = dp[i+1][j-1] + 2
                else:
                    dp[i][j] = max(dp[i+1][j], dp[i][j-1])

        # The length of the longest palindromic subsequence is stored in dp[0][len(t)-1]
        return dp[0][len(t)-1]

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Create a dictionary to store the frequency of each character in both strings
        char_freq_s = {}
        char_freq_t = {}

        # Count the frequency of each character in string s
        for char in s:
            if char in char_freq_s:
                char_freq_s[char] += 1
            else:
                char_freq_s[char] = 1

        # Count the frequency of each character in string t
        for char in t:
            if char in char_freq_t:
                char_freq_t[char] += 1
            else:
                char_freq_t[char] = 1

        # Initialize variables to keep track of the result and the maximum count of a character
        result = 0
        max_count = 0

        # Iterate through the character frequencies in string s
        for char, freq in char_freq_s.items():
            # If the character appears an even number of times, add it to the result
            if freq % 2 == 0:
                result += freq
            else:
                # Otherwise, add half of its occurrences to the result and increment the maximum count
                result += freq // 2
                max_count = max(max_count, freq)

        # Iterate through the character frequencies in string t
        for char, freq in char_freq_t.items():
            # If the character appears an odd number of times, add it to the result
            if freq % 2 == 1:
                result += freq
            else:
                # Otherwise, add half of its occurrences to the result and increment the maximum count
                result += freq // 2
                max_count = max(max_count, freq)

        # Add one more to the result if there is at least one character that appears an odd number of times
        return result + 1 if max_count > 0 else result

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Convert both strings to lowercase to ensure case insensitivity
        s = s.lower()
        t = t.lower()

        # Create a frequency dictionary for each string
        freq_s = {}
        freq_t = {}

        # Populate the frequency dictionaries
        for char in s:
            if char in freq_s:
                freq_s[char] += 1
            else:
                freq_s[char] = 1

        for char in t:
            if char in freq_t:
                freq_t[char] += 1
            else:
                freq_t[char] = 1

        # Calculate the length of the longest palindrome
        result = 0
        has_odd_count = False

        for count in set(freq_s.values()) | set(freq_t.values()):
            if count % 2 == 0:
                result += count
            else:
                result += count - 1
                has_odd_count = True

        # If there is at least one character with an odd count, add one more character to the result
        if has_odd_count:
            result += 1

        return result

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Check if either string is empty
        if not s or not t:
            return 0

        # Create a matrix to store the longest palindromic subsequence lengths
        dp = [[0] * len(t) for _ in range(len(s))]

        # Fill the diagonal of the DP table
        for i in range(len(s)):
            if s[i] == t[i]:
                dp[i][i] = 2

        # Handle the edge case where the first and last characters match
        if s[0] == t[-1]:
            dp[0][-1] = 2

        # Fill the rest of the DP table
        for length in range(2, min(len(s), len(t)) + 1):
            for i in range(len(s) - length + 1):
                j = i + length - 1
                if s[i] == t[j]:
                    dp[i][j] = dp[i+1][j-1] + 2
                else:
                    dp[i][j] = max(dp[i+1][j], dp[i][j-1])

        # The length of the longest palindromic subsequence is stored in dp[0][len(t)-1]
        return dp[0][len(t)-1]
